use super::*;
use semio_s_artifact_layout_layout_model::LayoutDrawingBirthSource;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn birth(row:&serde_json::Value)->LayoutDrawingBirth<String>{LayoutDrawingBirth{source:decode::<LayoutDrawingBirthSource>(&row["source"]),member:decode(&row["member"]),initial:row["initial"].as_str().unwrap().to_string()}}
fn close_owned<T:RetireOwned>(mut value:Option<T>){let mut close=RetainedCloneClose::default();while value.is_some()||!close.is_empty(){let d=close.next_owner_demands::<T>(value.is_some(),&None,256).unwrap();if !close.is_empty(){close.step_granted(grant(d)).unwrap();}else{close.begin_granted(&mut value,grant(d)).unwrap();}}}
fn observe(g:RetainedCloneGrant,f:impl FnOnce()->RetainedCloneStep)->RetainedCloneStep{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert!(step.progress().fits(g));step}
fn short(g:RetainedCloneGrant,axis:usize)->Option<RetainedCloneGrant>{let mut out=g;let n=match axis{0=>&mut out.maximum_items,1=>&mut out.maximum_copy_bytes,2=>&mut out.maximum_capacity_bytes,3=>&mut out.maximum_release_bytes,_=>&mut out.maximum_depth};if *n==0{None}else{*n-=1;Some(out)}}
fn close(owner:&mut DrawingBirthPreparation<String>){owner.begin_close();for at in 0..100000{if owner.terminal_is_empty(){return}let d=owner.close_demand(256).unwrap();let g=grant(d);for axis in 0..5{if let Some(short)=short(g,axis){assert_eq!(observe(short,||owner.close_step(short).unwrap()).progress(),Default::default())}}observe(g,||owner.close_step(g).unwrap());assert!(at<99999)}}
#[test]
fn parent_reference_copy_preserves_the_exact_original_birth_and_physical_ledger(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let original=birth(row);let payload=original.initial.as_ptr();let child=original.member.handle.child_id.as_ptr();let d=DrawingBirthPreparation::<String>::admission_demand();let(mut owner,paid)=DrawingBirthPreparation::admit(original,grant(d)).unwrap_or_else(|(e,_)|panic!("{e}"));assert!(paid.fits(grant(d)));for at in 0..100000{if owner.ready(){break}let d=owner.demand(256).unwrap();let g=grant(d);for axis in 0..5{if let Some(short)=short(g,axis){let phase=owner.phase;assert_eq!(observe(short,||owner.advance(short).unwrap()).progress(),Default::default());assert_eq!(owner.phase,phase)}}observe(g,||owner.advance(g).unwrap());assert!(at<99999)}let d=owner.take_demand().unwrap();let((parent,birth),paid)={let(value,p)=owner.take(grant(d)).unwrap();(value.unwrap(),p)};assert!(paid.fits(grant(d)));assert_eq!(parent,birth.member);assert_eq!(birth.initial.as_ptr(),payload);assert_eq!(birth.member.handle.child_id.as_ptr(),child);assert_ne!(parent.handle.child_id.as_ptr(),child);close(&mut owner);close_owned(Some(parent));close_owned(Some(birth));}}
#[test]
fn cancellation_closes_original_aliases_prepared_fields_and_unmoved_payloads(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){for cut in corpus["cuts"].as_array().unwrap(){let d=DrawingBirthPreparation::<String>::admission_demand();let(mut owner,_)=DrawingBirthPreparation::admit(birth(row),grant(d)).unwrap_or_else(|(e,_)|panic!("{e}"));for _ in 0..cut.as_u64().unwrap(){if owner.ready(){break}let d=owner.demand(256).unwrap();observe(grant(d),||owner.advance(grant(d)).unwrap());}close(&mut owner);}}}

#[test]
fn birth_admission_quotes_actual_heap_and_preserves_every_undergranted_original(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let d=DrawingBirthPreparation::<String>::admission_demand();let g=grant(d);for axis in 0..5{if let Some(under)=short(g,axis){let original=birth(row);let member=original.member.handle.child_id.as_ptr();let payload=original.initial.as_ptr();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||DrawingBirthPreparation::admit(original,under));assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,0);assert_eq!(heap.released_bytes,0);let Err((error,original))=result else{panic!("undergranted original birth was admitted")};assert_eq!(error.retained_progress(),Default::default());assert_eq!(original.member.handle.child_id.as_ptr(),member);assert_eq!(original.initial.as_ptr(),payload);close_owned(Some(original));}}let original=birth(row);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||DrawingBirthPreparation::admit(original,g));let(mut owner,paid)=result.unwrap_or_else(|(error,_)|panic!("{error}"));assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,paid.retained_capacity_bytes);assert_eq!(heap.released_bytes,paid.released_bytes);assert!(paid.fits(g));close(&mut owner);}}
